export const SENT = [{"at": 0, "end": 186, "text": "In this town of just 1,903 people, a retired couple found a way to beat the lottery."}, {"at": 196, "end": 209, "text": "Legally."}, {"at": 221, "end": 248, "text": "For 9 years."}, {"at": 265, "end": 459, "text": "In 2003, retired store owner Jerry Selbee read a brochure for a new Michigan game, Winfall."}, {"at": 463, "end": 531, "text": "He found the loophole in 3 minutes."}, {"at": 534, "end": 688, "text": "When the jackpot hit $5 million and nobody won, the money rolled down to the smaller prizes."}, {"at": 695, "end": 785, "text": "On those days, enough tickets put the math on your side."}, {"at": 791, "end": 814, "text": "Jerry tried it."}, {"at": 823, "end": 883, "text": "$3,600 in."}, {"at": 886, "end": 933, "text": "$6,300 back."}, {"at": 936, "end": 1132, "text": "He and his wife Marge formed a company with family and friends, and played 12 roll-downs, until Michigan ended the game."}, {"at": 1138, "end": 1210, "text": "Then they found a similar game in Massachusetts."}, {"at": 1213, "end": 1400, "text": "For 6 years, they drove 900 miles a trip, often betting over $600,000."}, {"at": 1406, "end": 1432, "text": "They weren't alone."}, {"at": 1435, "end": 1518, "text": "A group started by MIT students played it too."}, {"at": 1522, "end": 1665, "text": "In 2011, the Boston Globe broke the story, and many suspected a rigged game."}, {"at": 1670, "end": 1709, "text": "The state investigated."}, {"at": 1714, "end": 1792, "text": "The betting was legal, and no one's odds were hurt."}, {"at": 1798, "end": 1904, "text": "The state itself made $120 million from it."}, {"at": 1910, "end": 2107, "text": "In all, their company won over $26 million, nearly $8 million of it profit before tax."}, {"at": 2112, "end": 2149, "text": "Theirs went to family."}, {"at": 2155, "end": 2216, "text": "Sometimes the edge isn't luck."}, {"at": 2219, "end": 2264, "text": "It's reading the rules."}];
